begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_academy_programs(
 id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('ACPR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),code text unique not null,title_fr text not null,description_fr text,target_audience text[] not null default '{}',competency_framework jsonb not null default '{}',status text not null default 'draft' check(status in('draft','review','approved','published','suspended','archived')),territory_id uuid,tenant_id uuid references public.angelcare_marketplace_partner_tenants(id),owner_id uuid,published_at timestamptz,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_academy_courses(
 id uuid primary key default gen_random_uuid(),program_id uuid not null references public.angelcare_marketplace_academy_programs(id),catalog_item_id uuid references public.angelcare_marketplace_catalog_items(id),code text unique not null,slug text unique not null,title_fr text not null,description_fr text,duration_minutes int not null check(duration_minutes>0),delivery_mode text not null check(delivery_mode in('in_person','online_live','hybrid','self_paced')),prerequisite_rules jsonb not null default '{}',attendance_threshold numeric(5,2) not null default 80 check(attendance_threshold between 0 and 100),passing_score numeric(5,2) not null default 70 check(passing_score between 0 and 100),certificate_type text,certificate_validity_days int,territory_id uuid,tenant_id uuid references public.angelcare_marketplace_partner_tenants(id),status text not null default 'draft' check(status in('draft','review','approved','published','suspended','archived')),created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_academy_course_modules(
 id uuid primary key default gen_random_uuid(),course_id uuid not null references public.angelcare_marketplace_academy_courses(id) on delete cascade,module_key text not null,title_fr text not null,learning_objectives jsonb not null default '[]',content_reference text,duration_minutes int not null default 0,sort_order int not null default 0,status text not null default 'draft',unique(course_id,module_key));
create table if not exists public.angelcare_marketplace_academy_competencies(
 id uuid primary key default gen_random_uuid(),competency_key text unique not null,title_fr text not null,description_fr text,domain text not null,level_scale jsonb not null default '{}',required_evidence jsonb not null default '{}',status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_academy_course_competencies(
 course_id uuid not null references public.angelcare_marketplace_academy_courses(id) on delete cascade,competency_id uuid not null references public.angelcare_marketplace_academy_competencies(id),required_level text not null,evaluation_weight numeric(8,3) not null default 1,primary key(course_id,competency_id));
create table if not exists public.angelcare_marketplace_academy_b2b_training_orders(
 id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('B2BT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),organization_id uuid not null references public.angelcare_marketplace_b2b_organizations(id),crm_opportunity_id uuid references public.angelcare_marketplace_crm_opportunities(id),crm_quote_id uuid references public.angelcare_marketplace_crm_quotes(id),course_id uuid not null references public.angelcare_marketplace_academy_courses(id),contracted_seats int not null check(contracted_seats>0),custom_requirements jsonb not null default '{}',status text not null default 'draft' check(status in('draft','quoted','contracted','scheduling','active','completed','cancelled','archived')),starts_at timestamptz,ends_at timestamptz,territory_id uuid,tenant_id uuid references public.angelcare_marketplace_partner_tenants(id),owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_academy_cohorts(
 id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('COH-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),course_id uuid not null references public.angelcare_marketplace_academy_courses(id),b2b_training_order_id uuid references public.angelcare_marketplace_academy_b2b_training_orders(id),organization_id uuid references public.angelcare_marketplace_b2b_organizations(id),name text not null,status text not null default 'draft' check(status in('draft','enrollment_open','enrollment_closed','scheduled','active','assessment','completion_review','completed','cancelled','archived')),capacity int not null check(capacity>0),enrolled_count int not null default 0,waitlist_count int not null default 0,starts_at timestamptz,ends_at timestamptz,enrollment_opens_at timestamptz,enrollment_closes_at timestamptz,trainer_id uuid,site_reference text,territory_id uuid,tenant_id uuid references public.angelcare_marketplace_partner_tenants(id),owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_academy_sessions(
 id uuid primary key default gen_random_uuid(),cohort_id uuid not null references public.angelcare_marketplace_academy_cohorts(id) on delete cascade,title_fr text not null,starts_at timestamptz not null,ends_at timestamptz not null,session_date date generated always as ((starts_at at time zone 'UTC')::date) stored,delivery_mode text not null,location jsonb not null default '{}',trainer_id uuid,status text not null default 'scheduled' check(status in('scheduled','active','completed','cancelled','rescheduled')),attendance_locked boolean not null default false,territory_id uuid,tenant_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_academy_enrollments(
 id uuid primary key default gen_random_uuid(),cohort_id uuid not null references public.angelcare_marketplace_academy_cohorts(id) on delete cascade,learner_user_id uuid not null,learner_provider_id uuid,organization_id uuid references public.angelcare_marketplace_b2b_organizations(id),status text not null default 'enrolled' check(status in('invited','enrolled','waitlisted','active','completed','failed','withdrawn','cancelled')),attendance_rate numeric(5,2) not null default 0,completion_score numeric(5,2) not null default 0,enrolled_at timestamptz not null default now(),completed_at timestamptz,territory_id uuid,tenant_id uuid,unique(cohort_id,learner_user_id));
create table if not exists public.angelcare_marketplace_academy_attendance_records(
 id uuid primary key default gen_random_uuid(),session_id uuid not null references public.angelcare_marketplace_academy_sessions(id) on delete cascade,enrollment_id uuid not null references public.angelcare_marketplace_academy_enrollments(id) on delete cascade,status text not null check(status in('present','late','absent','authorized_absence','left_early')),check_in_at timestamptz,check_out_at timestamptz,recorded_by uuid not null,recorded_at timestamptz not null default now(),evidence jsonb not null default '{}',exception_flag boolean generated always as (status in('late','absent','left_early')) stored,territory_id uuid,tenant_id uuid,unique(session_id,enrollment_id));
create table if not exists public.angelcare_marketplace_academy_assessments(
 id uuid primary key default gen_random_uuid(),course_id uuid not null references public.angelcare_marketplace_academy_courses(id),cohort_id uuid references public.angelcare_marketplace_academy_cohorts(id),title_fr text not null,assessment_type text not null check(assessment_type in('knowledge','practical','observation','checklist','portfolio')),passing_score numeric(5,2) not null default 70,rubric jsonb not null default '{}',status text not null default 'draft' check(status in('draft','scheduled','active','closed','archived')),territory_id uuid,tenant_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_academy_assessment_results(
 id uuid primary key default gen_random_uuid(),assessment_id uuid not null references public.angelcare_marketplace_academy_assessments(id),enrollment_id uuid not null references public.angelcare_marketplace_academy_enrollments(id),evaluator_id uuid not null,score numeric(5,2) not null check(score between 0 and 100),passed boolean not null,evidence jsonb not null default '{}',status text not null default 'pending_review' check(status in('pending_review','approved','rejected','appealed','superseded')),assessed_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid,territory_id uuid,tenant_id uuid,unique(assessment_id,enrollment_id));
create table if not exists public.angelcare_marketplace_academy_certificates(
 id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('CERT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),enrollment_id uuid not null references public.angelcare_marketplace_academy_enrollments(id),learner_user_id uuid not null,learner_provider_id uuid,course_id uuid not null references public.angelcare_marketplace_academy_courses(id),competency_keys text[] not null default '{}',status text not null default 'draft' check(status in('draft','eligible','pending_approval','issued','active','expiring','expired','suspended','revoked','renewed','archived')),issued_at timestamptz,valid_from timestamptz,expires_at timestamptz,expiry_bucket text not null default 'future' check(expiry_bucket in('none','expired','next_30_days','future')),approved_by uuid,evidence_basis jsonb not null default '{}',predecessor_certificate_id uuid references public.angelcare_marketplace_academy_certificates(id),revocation_reason text,territory_id uuid,tenant_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_academy_certificate_events(
 id uuid primary key default gen_random_uuid(),certificate_id uuid not null references public.angelcare_marketplace_academy_certificates(id) on delete cascade,event_type text not null,from_status text,to_status text,reason text,actor_id uuid not null,evidence jsonb not null default '{}',created_at timestamptz not null default now());

create or replace function public.angelcare_marketplace_recalculate_enrollment_completion(p_enrollment_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare e public.angelcare_marketplace_academy_enrollments;sessions_count int;present_count int;avg_score numeric;begin select * into e from public.angelcare_marketplace_academy_enrollments where id=p_enrollment_id for update;if e.id is null then raise exception 'Enrollment not found';end if;select count(*) into sessions_count from public.angelcare_marketplace_academy_sessions where cohort_id=e.cohort_id and status<>'cancelled';select count(*) into present_count from public.angelcare_marketplace_academy_attendance_records ar join public.angelcare_marketplace_academy_sessions s on s.id=ar.session_id where ar.enrollment_id=e.id and s.cohort_id=e.cohort_id and ar.status in('present','late','left_early');select coalesce(avg(score),0) into avg_score from public.angelcare_marketplace_academy_assessment_results where enrollment_id=e.id and status in('pending_review','approved');update public.angelcare_marketplace_academy_enrollments set attendance_rate=case when sessions_count=0 then 0 else round((present_count::numeric/sessions_count)*100,2) end,completion_score=round(avg_score,2),updated_at=now() where id=e.id returning * into e;return to_jsonb(e);end$$;
create or replace function public.angelcare_marketplace_record_assessment_result(p_assessment_id uuid,p_enrollment_id uuid,p_score numeric,p_evidence jsonb,p_evaluator_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a public.angelcare_marketplace_academy_assessments;r public.angelcare_marketplace_academy_assessment_results;begin select * into a from public.angelcare_marketplace_academy_assessments where id=p_assessment_id;if a.id is null then raise exception 'Assessment not found';end if;insert into public.angelcare_marketplace_academy_assessment_results(assessment_id,enrollment_id,evaluator_id,score,passed,evidence,status) values(a.id,p_enrollment_id,p_evaluator_id,p_score,p_score>=a.passing_score,coalesce(p_evidence,'{}'),'pending_review') on conflict(assessment_id,enrollment_id) do update set evaluator_id=excluded.evaluator_id,score=excluded.score,passed=excluded.passed,evidence=excluded.evidence,status='pending_review',assessed_at=now() returning * into r;perform public.angelcare_marketplace_recalculate_enrollment_completion(p_enrollment_id);return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_transition_certificate(p_certificate_id uuid,p_action text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare c public.angelcare_marketplace_academy_certificates;e public.angelcare_marketplace_academy_enrollments;course public.angelcare_marketplace_academy_courses;target text;previous_status text;
begin
 select * into c from public.angelcare_marketplace_academy_certificates where id=p_certificate_id for update;
 if c.id is null then raise exception 'Certificate not found';end if;
 previous_status:=c.status;
 select * into e from public.angelcare_marketplace_academy_enrollments where id=c.enrollment_id;
 select * into course from public.angelcare_marketplace_academy_courses where id=c.course_id;
 if p_action='issue' then
  if e.attendance_rate<course.attendance_threshold or e.completion_score<course.passing_score or e.status not in('completed','active') then raise exception 'Certificate eligibility evidence is incomplete';end if;
  target:='active';
  update public.angelcare_marketplace_academy_certificates set status=target,issued_at=coalesce(issued_at,now()),valid_from=coalesce(valid_from,now()),expires_at=case when course.certificate_validity_days is null then expires_at else coalesce(expires_at,now()+make_interval(days=>course.certificate_validity_days)) end,expiry_bucket=case when course.certificate_validity_days is null then 'none' when course.certificate_validity_days<=30 then 'next_30_days' else 'future' end,approved_by=p_actor_id,updated_by=p_actor_id,updated_at=now() where id=c.id returning * into c;
 elsif p_action='suspend' then
  target:='suspended';update public.angelcare_marketplace_academy_certificates set status=target,updated_by=p_actor_id,updated_at=now() where id=c.id returning * into c;
 elsif p_action='revoke' then
  if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'revocation_reason is required';end if;
  target:='revoked';update public.angelcare_marketplace_academy_certificates set status=target,revocation_reason=p_reason,updated_by=p_actor_id,updated_at=now() where id=c.id returning * into c;
 elsif p_action='renew' then
  if c.status not in('active','expiring','expired') then raise exception 'Certificate is not renewable from current status';end if;
  target:='renewed';update public.angelcare_marketplace_academy_certificates set status=target,valid_from=now(),expires_at=case when course.certificate_validity_days is null then expires_at else now()+make_interval(days=>course.certificate_validity_days) end,expiry_bucket=case when course.certificate_validity_days is null then 'none' when course.certificate_validity_days<=30 then 'next_30_days' else 'future' end,updated_by=p_actor_id,updated_at=now() where id=c.id returning * into c;
 else raise exception 'Unsupported certificate action';end if;
 insert into public.angelcare_marketplace_academy_certificate_events(certificate_id,event_type,from_status,to_status,reason,actor_id,evidence) values(c.id,p_action,previous_status,target,p_reason,p_actor_id,jsonb_build_object('enrollment_id',c.enrollment_id,'source_version',c.updated_at));
 if c.learner_provider_id is not null then
  begin perform public.angelcare_marketplace_recalculate_provider_eligibility(c.learner_provider_id,p_actor_id);exception when undefined_function or undefined_table then null;end;
 end if;
 return to_jsonb(c);
end$$;

insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.academy.view','Voir Academy Command','Academy & Certification',false),('marketplace.academy.manage','Gérer Academy','Academy & Certification',true),('marketplace.academy.catalog.manage','Gérer le catalogue Academy','Academy & Certification',true),('marketplace.academy.cohorts.manage','Gérer les cohortes','Academy & Certification',true),('marketplace.academy.sessions.manage','Gérer les sessions','Academy & Certification',true),('marketplace.academy.attendance.manage','Gérer les présences','Academy & Certification',true),('marketplace.academy.assessments.manage','Gérer les évaluations','Academy & Certification',true),('marketplace.academy.certificates.issue','Émettre des certificats','Academy & Certification',true),('marketplace.academy.certificates.suspend','Suspendre des certificats','Academy & Certification',true),('marketplace.academy.certificates.revoke','Révoquer des certificats','Academy & Certification',true),('marketplace.academy.b2b.manage','Gérer la formation B2B','Academy & Certification',true),('marketplace.academy.trainer.access','Accéder à l’espace trainer','Academy & Certification',false),('marketplace.academy.learner.access','Accéder à l’espace learner','Academy & Certification',false)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.academy.%' on conflict do nothing;
insert into public.angelcare_marketplace_modules(module_key,name,description,route_prefix,module_type,audience,status,enabled,required_permissions,required_dependencies,territory_aware,tenant_aware,locale_aware,health_status,owner_role,introduced_by_mega_zip) values('academy-engine','Academy, Training & Certification','Catalogue, cohortes, présence, évaluations et autorité certificats.','/angelcare-marketplace/admin/academy','operating_engine',array['admin','executive','provider','tenant']::text[],'enabled',true,array['marketplace.academy.view']::text[],array['foundation','localization','territory-os']::text[],true,true,true,'healthy','academy_manager',16) on conflict(module_key) do update set status='enabled',enabled=true,route_prefix=excluded.route_prefix,required_permissions=excluded.required_permissions,updated_at=now();
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.academy.enabled','Academy Engine','Formation, évaluation et certification gouvernées.',true,'active','Ultra Delivery 4/5 · Original MZ16') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();

alter table public.angelcare_marketplace_academy_programs enable row level security;alter table public.angelcare_marketplace_academy_courses enable row level security;alter table public.angelcare_marketplace_academy_course_modules enable row level security;alter table public.angelcare_marketplace_academy_competencies enable row level security;alter table public.angelcare_marketplace_academy_course_competencies enable row level security;alter table public.angelcare_marketplace_academy_b2b_training_orders enable row level security;alter table public.angelcare_marketplace_academy_cohorts enable row level security;alter table public.angelcare_marketplace_academy_sessions enable row level security;alter table public.angelcare_marketplace_academy_enrollments enable row level security;alter table public.angelcare_marketplace_academy_attendance_records enable row level security;alter table public.angelcare_marketplace_academy_assessments enable row level security;alter table public.angelcare_marketplace_academy_assessment_results enable row level security;alter table public.angelcare_marketplace_academy_certificates enable row level security;alter table public.angelcare_marketplace_academy_certificate_events enable row level security;
revoke all on table public.angelcare_marketplace_academy_programs,public.angelcare_marketplace_academy_courses,public.angelcare_marketplace_academy_course_modules,public.angelcare_marketplace_academy_competencies,public.angelcare_marketplace_academy_course_competencies,public.angelcare_marketplace_academy_b2b_training_orders,public.angelcare_marketplace_academy_cohorts,public.angelcare_marketplace_academy_sessions,public.angelcare_marketplace_academy_enrollments,public.angelcare_marketplace_academy_attendance_records,public.angelcare_marketplace_academy_assessments,public.angelcare_marketplace_academy_assessment_results,public.angelcare_marketplace_academy_certificates,public.angelcare_marketplace_academy_certificate_events from anon,authenticated;
grant all on table public.angelcare_marketplace_academy_programs,public.angelcare_marketplace_academy_courses,public.angelcare_marketplace_academy_course_modules,public.angelcare_marketplace_academy_competencies,public.angelcare_marketplace_academy_course_competencies,public.angelcare_marketplace_academy_b2b_training_orders,public.angelcare_marketplace_academy_cohorts,public.angelcare_marketplace_academy_sessions,public.angelcare_marketplace_academy_enrollments,public.angelcare_marketplace_academy_attendance_records,public.angelcare_marketplace_academy_assessments,public.angelcare_marketplace_academy_assessment_results,public.angelcare_marketplace_academy_certificates,public.angelcare_marketplace_academy_certificate_events to service_role;
grant execute on function public.angelcare_marketplace_recalculate_enrollment_completion(uuid),public.angelcare_marketplace_record_assessment_result(uuid,uuid,numeric,jsonb,uuid),public.angelcare_marketplace_transition_certificate(uuid,text,text,uuid) to service_role;
create index if not exists ac_academy_cohort_scope_idx on public.angelcare_marketplace_academy_cohorts(territory_id,tenant_id,status,starts_at);create index if not exists ac_academy_certificate_expiry_idx on public.angelcare_marketplace_academy_certificates(status,expires_at);
commit;
